/// The `wsl --import <distro> <dir> <tarball> --version 2` argument vector. Pure, so it can be
/// unit-tested without WSL present.
pub(crate) fn import_args(distro: &str, install_dir: &str, tarball: &str) -> Vec<String> {
    vec![
        "--import".into(),
        distro.into(),
        install_dir.into(),
        tarball.into(),
        "--version".into(),
        "2".into(),
    ]
}
